      categoryMap.set(activity.category, (categoryMap.get(activity.category) || 0) + 1);
    });

    const total = allActivities.length;

    return Array.from(categoryMap.entries()).map(([category, count]) => ({
      category,
      count,
      percentage: total > 0 ? (count / total) * 100 : 0,
    }));
  }

