/**
 * Smart Student Hub global design system.
 * 
 * Implements professional academic styling with Inter/JetBrains Mono typography,
 * academic navy primary colors (hsl(222, 84%, 24%)), and dark mode support.
 * Integrates with Tailwind CSS and shadcn/ui components.
 */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');
@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600&display=swap');
@tailwind base;
@tailwind components;
@tailwind utilities;

/* Responsive Component Classes */
@layer components {

  /* Touch and Mobile Optimization - Simplified */
  .touch-friendly {
    @apply min-w-[44px] min-h-[44px] transition-all duration-200;
  }

  /* Safe Area Insets for Mobile Browsers */
  .safe-area-inset-top {
    padding-top: env(safe-area-inset-top);
  }

  .safe-area-inset-bottom {
    padding-bottom: env(safe-area-inset-bottom);
  }

  .safe-area-inset-left {
    padding-left: env(safe-area-inset-left);
  }

  .safe-area-inset-right {
    padding-right: env(safe-area-inset-right);
  }

  /* Mobile animations */
  @keyframes slide-in-right {
    from {
      transform: translateX(100%);
      opacity: 0;
    }
    to {
      transform: translateX(0);
      opacity: 1;
    }
  }
}

:root {
  /* Background Color Variants - Core Academic Palette */
  --background: hsl(220, 15%, 97%);
  --foreground: hsl(220, 40%, 6%);
  --card: hsl(0, 0%, 100%);
  --card-foreground: hsl(220, 35%, 8%);
  --popover: hsl(0, 0%, 100%);
  --popover-foreground: hsl(220, 35%, 8%);

  /* Primary Brand Colors - Academic Navy */
  --primary: hsl(222, 84%, 24%);
  --primary-foreground: hsl(0, 0%, 100%);
  --primary-50: hsl(222, 84%, 98%);
  --primary-100: hsl(222, 84%, 95%);
  --primary-200: hsl(222, 84%, 89%);
  --primary-300: hsl(222, 84%, 78%);
  --primary-400: hsl(222, 84%, 63%);
  --primary-500: hsl(222, 84%, 48%);
  --primary-600: hsl(222, 84%, 38%);
  --primary-700: hsl(222, 84%, 24%);
  --primary-800: hsl(222, 84%, 19%);
  --primary-900: hsl(222, 84%, 14%);

  /* Secondary Palette - Professional Grayscale */
  --secondary: hsl(220, 18%, 96%);
  --secondary-foreground: hsl(220, 30%, 8%);
  --secondary-50: hsl(220, 18%, 98%);
  --secondary-100: hsl(220, 18%, 96%);
  --secondary-200: hsl(220, 18%, 92%);
  --secondary-300: hsl(220, 18%, 85%);
  --secondary-400: hsl(220, 18%, 70%);
  --secondary-500: hsl(220, 18%, 55%);
  --secondary-600: hsl(220, 18%, 40%);
  --secondary-700: hsl(220, 18%, 28%);
  --secondary-800: hsl(220, 18%, 18%);
  --secondary-900: hsl(220, 18%, 10%);

  /* Neutral Colors - Academic Professional Palette */
  --muted: hsl(220, 16%, 97%);
  --muted-foreground: hsl(220, 25%, 42%);
  --accent: hsl(220, 16%, 95%);
  --accent-foreground: hsl(220, 30%, 12%);

  /* Status Colors - Institutional Compliance Standards */
  --destructive: hsl(0, 76%, 54%);
  --destructive-foreground: hsl(0, 0%, 100%);
  --success: hsl(139, 69%, 32%);
  --success-foreground: hsl(0, 0%, 100%);
  --success-50: hsl(139, 69%, 96%);
  --success-100: hsl(139, 69%, 91%);
  --success-200: hsl(139, 69%, 81%);
  --warning: hsl(30, 88%, 42%);
  --warning-foreground: hsl(0, 0%, 100%);
  --warning-50: hsl(30, 88%, 95%);
  --warning-100: hsl(30, 88%, 90%);
  --warning-200: hsl(30, 88%, 80%);
  --info: hsl(222, 84%, 50%);
  --info-foreground: hsl(0, 0%, 100%);
  --info-50: hsl(222, 84%, 96%);
  --info-100: hsl(222, 84%, 91%);
  --info-200: hsl(222, 84%, 81%);

  /* Border and Input Colors - Accessibility Compliant */
  --border: hsl(220, 20%, 84%);
  --input: hsl(220, 16%, 96%);
  --ring: hsl(222, 84%, 24%);

  /* Design System Variables */
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;

  /* Typography Scale */
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif;
  --font-mono: 'JetBrains Mono', 'Menlo', 'Monaco', 'Courier New', monospace;
  --font-serif: 'Georgia', 'Times New Roman', serif;

  /* Shadow Scale - Professional Interface Depth */
  --shadow-sm: 0 1px 2px 0 hsl(215, 25%, 12%, 0.05);
  --shadow-md: 0 4px 6px -1px hsl(215, 25%, 12%, 0.08), 0 2px 4px -1px hsl(215, 25%, 12%, 0.06);
  --shadow-lg: 0 10px 15px -3px hsl(215, 25%, 12%, 0.08), 0 4px 6px -2px hsl(215, 25%, 12%, 0.05);
  --shadow-xl: 0 20px 25px -5px hsl(215, 25%, 12%, 0.08), 0 10px 10px -5px hsl(215, 25%, 12%, 0.04);

  /* Animation Timing */
  --animation-fast: 150ms;
  --animation-normal: 250ms;
  --animation-slow: 350ms;
}

.dark {
  /* Dark Mode - Institutional Professional Theme */
  --background: hsl(215, 20%, 4%);
  --foreground: hsl(215, 20%, 95%);
  --card: hsl(215, 20%, 6%);
  --card-foreground: hsl(215, 20%, 95%);
  --popover: hsl(215, 20%, 6%);
  --popover-foreground: hsl(215, 20%, 95%);

  /* Primary Colors - Dark Mode Optimized */
  --primary: hsl(215, 85%, 60%);
  --primary-foreground: hsl(215, 20%, 6%);
  --primary-50: hsl(215, 85%, 10%);
  --primary-100: hsl(215, 85%, 15%);
  --primary-500: hsl(215, 85%, 50%);
  --primary-600: hsl(215, 85%, 55%);
  --primary-700: hsl(215, 85%, 60%);
  --primary-800: hsl(215, 85%, 65%);
  --primary-900: hsl(215, 85%, 70%);

  /* Secondary and Neutral Color System */
  --secondary: hsl(215, 15%, 10%);
  --secondary-foreground: hsl(215, 20%, 95%);
  --muted: hsl(215, 15%, 10%);
  --muted-foreground: hsl(215, 20%, 65%);
  --accent: hsl(215, 15%, 12%);
  --accent-foreground: hsl(215, 20%, 95%);

  /* Status Colors - Dark Mode Accessibility */
  --destructive: hsl(0, 75%, 65%);
  --destructive-foreground: hsl(215, 20%, 6%);
  --success: hsl(140, 75%, 55%);
  --success-foreground: hsl(215, 20%, 6%);
  --warning: hsl(38, 85%, 60%);
  --warning-foreground: hsl(215, 20%, 6%);
  --info: hsl(215, 85%, 65%);
  --info-foreground: hsl(215, 20%, 6%);

  /* Borders and Inputs */
  --border: hsl(215, 15%, 18%);
  --input: hsl(215, 15%, 15%);
  --ring: hsl(215, 85%, 60%);

  /* Dark Mode Shadows */
  --shadow-sm: 0 1px 2px 0 hsl(0, 0%, 0%, 0.15);
  --shadow-md: 0 4px 6px -1px hsl(0, 0%, 0%, 0.2), 0 2px 4px -1px hsl(0, 0%, 0%, 0.15);
  --shadow-lg: 0 10px 15px -3px hsl(0, 0%, 0%, 0.25), 0 4px 6px -2px hsl(0, 0%, 0%, 0.15);
  --shadow-xl: 0 20px 25px -5px hsl(0, 0%, 0%, 0.3), 0 10px 10px -5px hsl(0, 0%, 0%, 0.15);
}

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply font-sans antialiased bg-background text-foreground;
    font-family: var(--font-sans);
    font-feature-settings: 'rlig' 1, 'calt' 1, 'kern' 1;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
    line-height: 1.6;
    letter-spacing: -0.011em;
  }

  /* Academic Typography Scale - Institutional Standards */
  h1, h2, h3, h4, h5, h6 {
    @apply font-semibold tracking-tight text-foreground;
    line-height: 1.25;
    margin-bottom: 0.75em;
    font-weight: 600;
    letter-spacing: -0.025em;
  }

  h1 { 
    @apply text-4xl lg:text-5xl xl:text-6xl; 
    font-weight: 700;
    line-height: 1.1;
    letter-spacing: -0.04em;
  }

  h2 { 
    @apply text-3xl lg:text-4xl xl:text-5xl; 
    font-weight: 650;
    line-height: 1.15;
    letter-spacing: -0.035em;
  }

  h3 { 
    @apply text-2xl lg:text-3xl xl:text-4xl; 
    font-weight: 600;
    line-height: 1.2;
    letter-spacing: -0.03em;
  }

  h4 { 
    @apply text-xl lg:text-2xl xl:text-3xl; 
    font-weight: 600;
    line-height: 1.25;
    letter-spacing: -0.025em;
  }

  h5 { 
    @apply text-lg lg:text-xl xl:text-2xl; 
    font-weight: 550;
    line-height: 1.3;
    letter-spacing: -0.02em;
  }

  h6 { 
    @apply text-base lg:text-lg xl:text-xl; 
    font-weight: 550;
    line-height: 1.35;
    letter-spacing: -0.015em;
  }

  /* Text Styles - Academic Standards */
  p {
    line-height: 1.65;
    margin-bottom: 1.25em;
    color: hsl(var(--foreground));
    font-weight: 400;
  }

  /* Link Styles - Institutional Standards */
  a {
    color: hsl(var(--primary));
    text-decoration: none;
    font-weight: 500;
    transition: color 0.2s ease-in-out;
  }

  a:hover {
    color: hsl(var(--primary-600));
    text-decoration: underline;
    text-decoration-thickness: 1px;
    text-underline-offset: 3px;
  }

  /* List Styles - Academic Documentation */
  ul, ol {
    margin-bottom: 1.5em;
    padding-left: 1.75em;
  }

  li {
    line-height: 1.65;
    margin-bottom: 0.5em;
    color: hsl(var(--foreground));
  }

  /* Code and Monospace - Technical Documentation */
  code {
    font-family: var(--font-mono);
    font-size: 0.875em;
    font-weight: 500;
    background-color: hsl(var(--muted));
    color: hsl(var(--foreground));
    padding: 0.125rem 0.375rem;
    border-radius: 0.25rem;
    border: 1px solid hsl(var(--border));
  }

  pre {
    font-family: var(--font-mono);
    background-color: hsl(var(--muted));
    color: hsl(var(--foreground));
    padding: 1rem 1.25rem;
    border-radius: 0.5rem;
    border: 1px solid hsl(var(--border));
    overflow-x: auto;
    margin-bottom: 1.5em;
    line-height: 1.45;
  }

  /* Small Text - Supporting Information */
  small {
    font-size: 0.875em;
    color: hsl(var(--muted-foreground));
    font-weight: 400;
    line-height: 1.5;
  }

  /* Text Emphasis - Academic Hierarchy */
  strong, b {
    font-weight: 600;
    color: hsl(var(--foreground));
  }

  em, i {
    font-style: italic;
    font-weight: 450;
  }
}

@layer components {
  /* Dashboard Components - Institutional Interface */
  .dashboard-card {
    @apply bg-card border border-border rounded-lg shadow-sm hover:shadow-md transition-all duration-300;
    backdrop-filter: blur(8px);
    border: 1px solid hsl(var(--border));
  }

  .stat-card {
    @apply bg-card border border-border rounded-lg p-6 shadow-sm hover:shadow-lg transition-all duration-300 relative overflow-hidden;
    border: 1px solid hsl(var(--border));
    background: linear-gradient(135deg, hsl(var(--card)), hsl(var(--card) / 0.98));
  }

  .stat-card::before {
    content: '';
    @apply absolute inset-0 opacity-0 transition-opacity duration-300;
    background: linear-gradient(135deg, hsl(var(--primary) / 0.03), transparent);
  }

  .stat-card:hover::before {
    opacity: 1;
  }

  .stat-card:hover {
    border-color: hsl(var(--primary) / 0.2);
    box-shadow: 0 8px 25px -5px hsl(var(--primary) / 0.1), 0 10px 10px -5px hsl(var(--primary) / 0.04);
  }

  /* Navigation components */
  .nav-item {
    @apply flex items-center px-4 py-3 text-sm font-medium text-muted-foreground hover:text-foreground hover:bg-accent rounded-md transition-all duration-200;
    border-left: 3px solid transparent;
  }

  .nav-item:hover {
    border-left-color: hsl(var(--primary) / 0.3);
    background: linear-gradient(90deg, hsl(var(--accent)), hsl(var(--card)));
  }

  .nav-item.active {
    @apply text-primary bg-accent;
    border-left-color: hsl(var(--primary));
    background: linear-gradient(90deg, hsl(var(--primary) / 0.08), hsl(var(--card)));
    font-weight: 600;
  }

  /* Button components */
  .btn-primary {
    @apply bg-primary text-primary-foreground hover:bg-primary px-4 py-2 rounded-md text-sm font-medium transition-all duration-200 inline-flex items-center justify-center;
    box-shadow: 0 2px 4px hsl(var(--primary) / 0.2);
    border: 1px solid hsl(var(--primary));
  }

  .btn-primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 8px hsl(var(--primary) / 0.25);
  }

  .btn-secondary {
    @apply bg-secondary text-secondary-foreground hover:bg-secondary px-4 py-2 rounded-md text-sm font-medium transition-all duration-200 inline-flex items-center justify-center;
    border: 1px solid hsl(var(--border));
    box-shadow: 0 1px 3px hsl(var(--border) / 0.3);
  }

  .btn-secondary:hover {
    border-color: hsl(var(--primary) / 0.3);
    box-shadow: 0 2px 6px hsl(var(--primary) / 0.15);
  }

  /* Status Badges - Academic Workflow */
  .status-badge {
    @apply inline-flex items-center px-3 py-1 rounded-full text-xs font-semibold border transition-all duration-200;
    letter-spacing: 0.05em;
    text-transform: uppercase;
  }

  .status-pending {
    background: linear-gradient(135deg, hsl(var(--warning-50)), hsl(var(--warning-100)));
    color: hsl(var(--warning-foreground));
    border: 1px solid hsl(var(--warning-200));
    box-shadow: 0 1px 3px hsl(var(--warning) / 0.2);
  }

  .status-approved {
    background: linear-gradient(135deg, hsl(var(--success-50)), hsl(var(--success-100)));
    color: hsl(var(--success-foreground));
    border: 1px solid hsl(var(--success-200));
    box-shadow: 0 1px 3px hsl(var(--success) / 0.2);
  }

  .status-rejected {
    @apply bg-red-50 text-red-700 border-red-200 dark:bg-red-900/20 dark:text-red-400 dark:border-red-800;
    background: linear-gradient(135deg, hsl(0, 75%, 96%), hsl(0, 75%, 92%));
    box-shadow: 0 1px 3px hsl(0, 75%, 54%, 0.2);
  }

  /* Form components */
  .form-input {
    @apply w-full px-3 py-2 border border-border rounded-md bg-background text-foreground placeholder-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent transition-all duration-200;
    box-shadow: 0 1px 3px hsl(var(--border) / 0.2);
  }

  .form-input:focus {
    box-shadow: 0 2px 6px hsl(var(--primary) / 0.15), 0 0 0 2px hsl(var(--primary) / 0.2);
  }

  .form-select {
    @apply w-full px-3 py-2 border border-border rounded-md bg-background text-foreground focus:outline-none focus:ring-2 focus:ring-primary focus:border-transparent transition-all duration-200;
    box-shadow: 0 1px 3px hsl(var(--border) / 0.2);
  }

  .form-select:focus {
    box-shadow: 0 2px 6px hsl(var(--primary) / 0.15), 0 0 0 2px hsl(var(--primary) / 0.2);
  }

  .form-label {
    @apply block text-sm font-semibold text-foreground mb-2;
    letter-spacing: 0.025em;
  }

  /* Upload area */
  .upload-area {
    @apply border-2 border-dashed border-border rounded-lg p-8 text-center bg-muted hover:bg-muted transition-colors cursor-pointer;
  }

  .upload-area.drag-over {
    @apply border-primary bg-accent;
  }

  /* Progress bar */
  .progress-bar {
    @apply w-full bg-secondary rounded-full h-2;
  }

  .progress-fill {
    @apply bg-primary h-2 rounded-full transition-all duration-300;
  }

  /* Table styling */
  .data-table {
    @apply w-full border-collapse;
  }

  .data-table th {
    @apply bg-muted border-b border-border px-4 py-3 text-left text-xs font-medium text-muted-foreground uppercase tracking-wider;
  }

  .data-table td {
    @apply border-b border-border px-4 py-3 text-sm text-foreground;
  }

  .data-table tr:hover {
    @apply bg-muted;
  }
}

@layer utilities {
  /* Interface Animations - Academic Standards */
  .fade-in {
    animation: fadeIn 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .slide-up {
    animation: slideUp 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .scale-in {
    animation: scaleIn 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  }

  /* Loading States - User Experience Standards */
  .loading-pulse {
    animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
  }

  .loading-shimmer {
    background: linear-gradient(90deg, 
      hsl(var(--muted)) 0%, 
      hsl(var(--accent)) 50%, 
      hsl(var(--muted)) 100%);
    background-size: 200% 100%;
    animation: shimmer 1.5s infinite;
  }

  /* Glass morphism effect */
  .glass {
    backdrop-filter: blur(16px) saturate(180%);
    background-color: rgba(255, 255, 255, 0.75);
    border: 1px solid rgba(209, 213, 219, 0.3);
  }

  .glass.dark {
    background-color: rgba(17, 25, 40, 0.75);
    border: 1px solid rgba(255, 255, 255, 0.125);
  }

  @keyframes fadeIn {
    from { 
      opacity: 0; 
      transform: translateY(16px); 
    }
    to { 
      opacity: 1; 
      transform: translateY(0); 
    }
  }

  @keyframes slideUp {
    from { 
      opacity: 0; 
      transform: translateY(24px); 
    }
    to { 
      opacity: 1; 
      transform: translateY(0); 
    }
  }

  @keyframes scaleIn {
    from { 
      opacity: 0; 
      transform: scale(0.95); 
    }
    to { 
      opacity: 1; 
      transform: scale(1); 
    }
  }

  @keyframes shimmer {
    0% {
      background-position: -200% 0;
    }
    100% {
      background-position: 200% 0;
    }
  }

  /* Responsive Typography */
  .text-display {
    @apply text-4xl md:text-5xl lg:text-6xl xl:text-7xl font-bold tracking-tight;
  }

  .text-headline {
    @apply text-2xl md:text-3xl lg:text-4xl font-semibold tracking-tight;
  }

  .text-subheadline {
    @apply text-lg md:text-xl lg:text-2xl font-medium;
  }

  /* Professional Focus States */
  .focus-ring {
    @apply focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 dark:focus:ring-offset-background;
  }

  /* Enhanced Borders */
  .border-gradient {
    border-image: linear-gradient(135deg, 
      hsl(var(--primary)), 
      hsl(var(--primary-500))) 1;
  }

  /* Content Visibility Optimization */
  .content-visibility-auto {
    content-visibility: auto;
    contain-intrinsic-size: 0 500px;
  }

  /* Advanced Responsive Grid System */
  .grid-responsive {
    @apply grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: clamp(1rem, 2.5vw, 2rem);
  }

  .grid-dashboard {
    @apply grid gap-4 xs:gap-5 sm:gap-6 md:gap-7 lg:gap-8 xl:gap-10 2xl:gap-12 3xl:gap-14;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 320px), 1fr));
  }

  /* Fluid Typography System */
  .text-fluid-xs { font-size: clamp(0.75rem, 0.5rem + 1vw, 0.875rem); }
  .text-fluid-sm { font-size: clamp(0.875rem, 0.625rem + 1.25vw, 1rem); }
  .text-fluid-base { font-size: clamp(1rem, 0.75rem + 1.5vw, 1.125rem); }
  .text-fluid-lg { font-size: clamp(1.125rem, 0.875rem + 1.75vw, 1.25rem); }
  .text-fluid-xl { font-size: clamp(1.25rem, 1rem + 2vw, 1.5rem); }
  .text-fluid-2xl { font-size: clamp(1.5rem, 1.25rem + 2.5vw, 2rem); }
  .text-fluid-3xl { font-size: clamp(1.875rem, 1.5rem + 3vw, 2.5rem); }
  .text-fluid-4xl { font-size: clamp(2.25rem, 1.75rem + 3.5vw, 3rem); }

  /* Responsive Spacing System */
  .space-responsive-tight {
    @apply space-y-2 xs:space-y-3 sm:space-y-4 md:space-y-5 lg:space-y-6 xl:space-y-7 2xl:space-y-8 3xl:space-y-10;
  }

  .space-responsive-normal {
    @apply space-y-4 xs:space-y-5 sm:space-y-6 md:space-y-7 lg:space-y-8 xl:space-y-10 2xl:space-y-12 3xl:space-y-14;
  }

  .space-responsive-relaxed {
    @apply space-y-6 xs:space-y-7 sm:space-y-8 md:space-y-10 lg:space-y-12 xl:space-y-14 2xl:space-y-16 3xl:space-y-20;
  }

  /* Touch-Friendly Interactive Elements */
  .touch-target {
    @apply min-w-[44px] min-h-[44px] touch-manipulation;
  }

  /* Enhanced Mobile Navigation */
  .mobile-nav-item {
    @apply flex items-center w-full min-h-[52px] px-4 py-3 text-base font-medium touch-manipulation transition-all duration-200;
    @apply hover:bg-accent active:bg-muted focus:bg-accent focus:outline-none;
    -webkit-tap-highlight-color: transparent;
  }

  .mobile-nav-item:active {
    transform: scale(0.98);
  }

  /* Mobile Menu Animations */
  .mobile-menu-enter {
    animation: mobileMenuSlideIn 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .mobile-menu-exit {
    animation: mobileMenuSlideOut 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }

  @keyframes mobileMenuSlideIn {
    from {
      transform: translateX(100%);
      opacity: 0;
    }
    to {
      transform: translateX(0);
      opacity: 1;
    }
  }

  @keyframes mobileMenuSlideOut {
    from {
      transform: translateX(0);
      opacity: 1;
    }
    to {
      transform: translateX(100%);
      opacity: 0;
    }
  }

  /* Touch-Optimized Button States */
  .touch-button {
    @apply touch-manipulation transition-all duration-200;
    -webkit-tap-highlight-color: transparent;
  }

  .touch-button:active {
    transform: scale(0.96);
  }

  /* Responsive Mobile Search */
  .mobile-search {
    @apply touch-manipulation transition-all duration-200;
  }

  .mobile-search:focus {
    @apply ring-2 ring-primary ring-offset-2;
  }

  /* Enhanced Dropdown for Touch */
  .touch-dropdown-item {
    @apply min-h-[44px] touch-manipulation transition-all duration-200;
    -webkit-tap-highlight-color: transparent;
  }

  .touch-dropdown-item:active {
    transform: scale(0.98);
  }

  /* Safe Area Insets for Mobile Devices */
  .pb-safe-area-inset-bottom {
    padding-bottom: max(1rem, env(safe-area-inset-bottom));
  }

  .pt-safe-area-inset-top {
    padding-top: max(1rem, env(safe-area-inset-top));
  }

  .pl-safe-area-inset-left {
    padding-left: max(1rem, env(safe-area-inset-left));
  }

  .pr-safe-area-inset-right {
    padding-right: max(1rem, env(safe-area-inset-right));
  }

  /* Advanced Container Queries Support */
  @container (min-width: 20rem) {
    .container-responsive {
      @apply p-4;
    }
  }

  @container (min-width: 32rem) {
    .container-responsive {
      @apply p-6;
    }
  }

  @container (min-width: 48rem) {
    .container-responsive {
      @apply p-8;
    }
  }

  /* Performance Optimizations */
  .transform-gpu {
    transform: translateZ(0);
    will-change: transform;
  }

  .contain-layout {
    contain: layout;
  }

  .contain-paint {
    contain: paint;
  }

  /* Device-Specific Responsive Breakpoints */

  /* Mobile Phones: 320px-640px */
  @media (min-width: 320px) and (max-width: 640px) {
    .mobile-optimized {
      font-size: 16px; /* Prevents zoom on iOS */
    }

    .nav-mobile-phone {
