// Enhanced Animated Counter with Spring Physics
const AnimatedCounter = ({ 
  end, 
  duration = 2, 
  suffix = "", 
  prefix = "", 
  decimals = 0,
  fontSize = "text-4xl" 
}: { 
  end: number; 
  duration?: number; 
  suffix?: string; 
  prefix?: string;
  decimals?: number;
  fontSize?: string;
}) => {
  const { ref, inView } = useIntersectionObserver({
    threshold: 0.3,
    triggerOnce: true,
  });

  const springProps = useSpring({
    from: { number: 0 },
    to: { number: inView ? end : 0 },
    config: { tension: 100, friction: 25 },
  });

  return (
    <span ref={ref} data-testid={`animated-counter-${end}`} className={fontSize}>
      {inView ? (
        <CountUp
          start={0}
          end={end}
          duration={duration}
          decimals={decimals}
          prefix={prefix}
          suffix={suffix}
          separator=","
          preserveValue
        />
      ) : (
        `${prefix}0${suffix}`
      )}
    </span>
  );
};

