/**
 * Navigation Component for Smart Student Hub
 * 
 * This comprehensive navigation component serves as the primary institutional header
 * for the Smart Student Hub platform, providing essential navigation, user management,
 * and institutional branding elements for Higher Education Institution environments.
 * 
 * Core Institutional Features:
 * - Professional institutional branding with official logo and title
 * - Main navigation menu with academic sections and functionality
 * - Comprehensive search functionality for institutional records and documents
 * - Real-time notification system for faculty approvals and system updates
 * - Role-based user profile management with authentication controls
 * - Professional dropdown menus with institutional-grade options
 * - Responsive design optimized for academic environments with mobile hamburger menu
 * 
 * Navigation Components:
 * - Institution Logo: Professional branding element with institutional identity
 * - Main Menu: Academic Dashboard, Activities, Achievement Submission, Portfolio
 * - Search Bar: Comprehensive search across student records, activities, and documents
 * - Notifications: Real-time alerts for faculty approvals, system updates, and deadlines
 * - User Profile: Avatar, name, role display with dropdown menu for account management
 * - Authentication: Login/Signup buttons for guests, logout functionality for users
 * - Mobile Menu: Responsive hamburger menu for small screen devices
 * 
 * User Experience Design:
 * - Clean, professional interface suitable for academic institutional environments
 * - Consistent with Higher Education Institution design standards and accessibility guidelines
 * - Responsive layout ensuring optimal display across desktop, tablet, and mobile devices
 * - Professional color scheme aligned with institutional branding requirements
 * - Accessible design following WCAG guidelines for inclusive education environments
 * 
 * Security & Authentication:
 * - Integrated with institutional authentication systems (LDAP, SAML, OAuth)
 * - Role-based access control reflecting institutional hierarchy (student, faculty, admin)
 * - Secure session management with automatic timeout for institutional security compliance
 * - Protected routes ensuring appropriate access to institutional data and functionality
 * 
 * Technical Implementation:
 * - Built with React functional components and modern hooks for optimal performance
 * - TypeScript integration ensuring type safety and maintainable codebase
 * - Responsive CSS classes using Tailwind CSS for consistent styling
 * - Accessible ARIA labels and semantic HTML for inclusive design
 * - Real-time state management for notifications and user status updates
 * - Mobile-first responsive design with proper breakpoints
 * 
 * Integration Points:
 * - Authentication hook integration for user state management and role verification
 * - Notification system integration for real-time alerts and faculty communications
 * - Search functionality connected to institutional databases and document repositories
 * - User profile management linked to institutional directory and account systems
 * - Logout functionality integrated with institutional session management protocols
 * - Routing integration with wouter for seamless navigation throughout the platform
 */

import { useState } from "react";
import { Link, useLocation } from "wouter";
import { useAuth } from "@/hooks/useAuth";
import { signOutUser } from "@/firebase/auth";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Sheet, SheetContent, SheetTrigger } from "@/components/ui/sheet";
import { cn } from "@/lib/utils";
import { 
  GraduationCap, 
  Search, 
  Bell, 
  ChevronDown, 
  User, 
  Settings, 
  LogOut, 
  Menu,
  LayoutDashboard,
  ClipboardList,
  Upload,
  FolderOpen
} from "lucide-react";

/**
 * Navigation Menu Items Configuration
 * 
 * Defines the main navigation items available to all users in the Smart Student Hub.
 * Each item includes routing information, display text, and iconography for consistent
 * institutional navigation experience.
 */
const navigationItems = [
  {
    href: "/",
    label: "Academic Dashboard",
    icon: LayoutDashboard,
    testId: "nav-academic-dashboard"
  },
  {
    href: "/activities",
    label: "Academic Activities",
    icon: ClipboardList,
    testId: "nav-academic-activities"
  },
  {
    href: "/upload",
    label: "Submit Achievement",
    icon: Upload,
    testId: "nav-submit-achievement"
  },
  {
    href: "/portfolio",
    label: "Academic Portfolio",
    icon: FolderOpen,
    testId: "nav-academic-portfolio"
  }
];

/**
 * Navigation Link Component
 * 
 * Renders individual navigation links with proper styling and active state management.
 * Provides consistent styling for both desktop and mobile navigation menus.
 * 
 * @param href - Route path for the navigation link
 * @param label - Display text for the navigation item
 * @param icon - Lucide icon component for visual identification
 * @param testId - Test identifier for automated testing
 * @param className - Additional CSS classes for styling
 * @param onClick - Optional click handler for mobile menu interactions
 */
interface NavLinkProps {
  href: string;
  label: string;
  icon: typeof LayoutDashboard;
  testId: string;
  className?: string;
  onClick?: () => void;
}

function NavLink({ href, label, icon: Icon, testId, className, onClick }: NavLinkProps) {
  const [location] = useLocation();
  const isActive = location === href;

  return (
    <Button
      variant={isActive ? "default" : "ghost"}
      className={cn(
        "flex items-center gap-2 justify-start transition-all duration-200",
        "h-10 px-3 text-sm",
        "min-h-[44px] min-w-[44px]", // Touch-friendly minimum size
        "hover:scale-105 active:scale-95",
        className
      )}
      data-testid={testId}
      asChild
    >
      <Link href={href} onClick={onClick}>
        <Icon className="w-4 h-4 flex-shrink-0" />
        <span className="font-medium truncate">{label}</span>
      </Link>
    </Button>
  );
}

/**
 * Navigation Component
 * 
 * Main navigation header component providing institutional branding, main navigation menu,
 * search functionality, notifications, and user profile management for the Smart Student Hub platform.
 * 
 * Features:
 * - Professional institutional branding with logo and title
 * - Main navigation menu with academic sections (Dashboard, Activities, Submit, Portfolio)
 * - Comprehensive search functionality for records and documents (authenticated users)
 * - Real-time notification system with badge indicators (authenticated users)
 * - User profile dropdown with account management options (authenticated users)
 * - Login and Signup buttons for unauthenticated users
 * - Responsive design with mobile hamburger menu for all device types
 * - Role-based access control and secure authentication
 * 
 * @returns {JSX.Element} Complete navigation header with all institutional features
 */
export default function Navigation() {
  // Authentication hook for user state management and role verification
  const { user } = useAuth();


  // Local state for search functionality with institutional record integration
  const [searchQuery, setSearchQuery] = useState("");

  // Mobile menu open state for hamburger menu control
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  /**
   * Logout Handler
   * 
   * Handles secure user logout using Firebase authentication.
   * Signs out the user and redirects to the signin page.
   */
  const handleLogout = async () => {
    try {
      closeMobileMenu();
      await signOutUser();
      // signOutUser now handles the redirect
    } catch (error) {
      console.error("Logout failed:", error);
    }
  };

  /**
   * Mobile Menu Close Handler
   * 
   * Closes the mobile navigation menu when a navigation item is selected.
   * Provides smooth user experience on mobile devices.
   */
  const closeMobileMenu = () => {
    setMobileMenuOpen(false);
  };

  return (
    <header className="bg-card border-b border-border sticky top-0 z-50 shadow-sm" data-testid="navigation-header">
      <div className="container max-w-none px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between min-h-[64px] lg:min-h-[72px]">

          {/* Institutional Logo and Branding Section */}
          <div className="flex items-center gap-3 lg:gap-4">
            {/* Professional Institution Logo with simplified responsive sizing */}
            <Link href="/" className="focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 rounded-lg">
              <div className="w-12 h-12 lg:w-14 lg:h-14 bg-primary rounded-lg flex items-center justify-center cursor-pointer transition-all duration-200 hover:scale-105" data-testid="logo-institution">
                <GraduationCap className="w-7 h-7 lg:w-8 lg:h-8 text-primary-foreground" />
              </div>
            </Link>

            {/* Institutional Name and System Designation - Simplified sizing */}
            <div className="hidden sm:block">
              <h1 className="text-lg lg:text-xl font-semibold text-foreground leading-tight" data-testid="text-app-title">
                Smart Student Hub
              </h1>
              <p className="text-sm text-muted-foreground" data-testid="text-app-subtitle">
                Excellence Management System
              </p>
            </div>
          </div>

          {/* Desktop Navigation Menu - Simplified responsive breakpoints */}
          <nav className="hidden lg:flex items-center gap-2" data-testid="nav-desktop-menu">
            {navigationItems.map((item) => (
              <NavLink
                key={item.href}
                href={item.href}
                label={item.label}
                icon={item.icon}
                testId={item.testId}
                className="w-auto"
              />
            ))}
          </nav>

          {/* Navigation Actions and User Interface Section */}
          <div className="flex items-center gap-3">

            {/* Advanced Search Bar for Institutional Records (Authenticated Users Only) */}
            {user && (
              <div className="relative hidden sm:block">
                <Input
                  type="text"
                  placeholder="Search..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-40 lg:w-64 pl-9 h-10 text-sm transition-all duration-200"
                  data-testid="input-search"
                />
                {/* Search Icon with Professional Styling */}
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              </div>
            )}

            {/* Real-time Notification System (Authenticated Users Only) */}
            {user && (
              <Button 
                variant="ghost" 
                size="icon" 
                className="relative h-10 w-10 transition-all duration-200 hover:bg-accent"
                data-testid="button-notifications"
              >
                <Bell className="w-5 h-5" />
                {/* Notification Badge for Real-time Alerts */}
                <Badge 
                  variant="destructive" 
                  className="absolute -top-1 -right-1 w-2.5 h-2.5 p-0 rounded-full animate-pulse"
                  data-testid="badge-notification-count"
                />
              </Button>
            )}

            {/* Authentication Buttons for Unauthenticated Users */}
            {!user && (
              <div className="hidden sm:flex items-center gap-2">
                <Button variant="ghost" size="sm" className="h-10 px-4 text-sm" data-testid="button-login" asChild>
                  <Link href="/login">
                    Login
                  </Link>
                </Button>
                <Button size="sm" className="h-10 px-4 text-sm" data-testid="button-signup" asChild>
                  <Link href="/signup">
                    Sign Up
                  </Link>
                </Button>
              </div>
            )}

            {/* User Profile and Account Management Dropdown (Authenticated Users Only) - Enhanced touch optimization */}
            {user && (
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button 
                    variant="ghost" 
                    className="group flex items-center gap-2 p-2 transition-all duration-200"
                    data-testid="button-user-menu"
                  >
                    {/* Professional User Avatar */}
                    <Avatar className="w-8 h-8 ring-2 ring-transparent hover:ring-primary/20 transition-all duration-200">
                      <AvatarImage src={user.profileImageUrl || ""} />
                      <AvatarFallback className="text-sm font-semibold">
                        {user.firstName?.[0]}{user.lastName?.[0]}
                      </AvatarFallback>
                    </Avatar>

                    {/* User Information Display */}
                    <div className="hidden lg:block text-left">
                      <div className="text-sm font-medium text-foreground truncate max-w-32" data-testid="text-user-name">
                        {user.firstName} {user.lastName}
                      </div>
                      <div className="text-xs text-muted-foreground capitalize truncate" data-testid="text-user-role">
                        {user.role}
                      </div>
                    </div>

                    {/* Dropdown Indicator Icon */}
                    <ChevronDown className="hidden sm:block w-4 h-4 transition-transform duration-200 group-data-[state=open]:rotate-180" />
                  </Button>
                </DropdownMenuTrigger>

                {/* User Account Management Menu */}
                <DropdownMenuContent align="end" className="w-56 shadow-lg">
                  {/* Account Profile Management */}
                  <DropdownMenuItem className="min-h-[44px]" data-testid="menu-item-profile" asChild>
                    <Link href="/profile">
                      <User className="mr-3 h-4 w-4" />
                      <span className="text-sm">Account Profile</span>
                    </Link>
                  </DropdownMenuItem>

                  {/* System Preferences and Settings */}
                  <DropdownMenuItem className="min-h-[44px]" data-testid="menu-item-settings">
                    <Settings className="mr-3 h-4 w-4" />
                    <span className="text-sm">System Preferences</span>
                  </DropdownMenuItem>

                  {/* Secure Logout Functionality */}
                  <DropdownMenuItem onClick={handleLogout} className="min-h-[44px] text-destructive hover:text-destructive" data-testid="menu-item-logout">
                    <LogOut className="mr-3 h-4 w-4" />
                    <span className="text-sm">Sign Out</span>
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            )}

            {/* Mobile Menu Trigger (Hamburger Button) - Enhanced touch target */}
            <Sheet open={mobileMenuOpen} onOpenChange={setMobileMenuOpen}>
              <SheetTrigger asChild>
                <Button 
                  variant="ghost" 
                  size="icon" 
                  className="lg:hidden h-10 w-10 transition-all duration-200 hover:bg-accent active:scale-95"
                  data-testid="button-mobile-menu"
                  aria-label="Open mobile navigation menu"
                >
                  <Menu className="w-6 h-6" />
                </Button>
              </SheetTrigger>

              {/* Mobile Navigation Menu Content */}
              <SheetContent side="right" className="w-[85vw] max-w-sm" data-testid="sheet-mobile-menu">
                <div className="flex flex-col h-full">

                  {/* Mobile Menu Header */}
                  <div className="flex items-center gap-4 pb-6 border-b border-border/50">
                    <div className="w-14 h-14 bg-primary rounded-xl flex items-center justify-center shadow-lg">
                      <GraduationCap className="w-8 h-8 text-primary-foreground" />
                    </div>
                    <div>
                      <h2 className="text-lg font-bold text-foreground leading-tight">Smart Student Hub</h2>
                      <p className="text-sm text-muted-foreground leading-snug">Excellence Management</p>
                    </div>
                  </div>

                  {/* Mobile Navigation Menu Items */}
                  <nav className="flex flex-col gap-2 py-6" data-testid="nav-mobile-menu">
                    {navigationItems.map((item) => (
                      <NavLink
                        key={item.href}
                        href={item.href}
                        label={item.label}
                        icon={item.icon}
                        testId={`mobile-${item.testId}`}
                        className="w-full justify-start text-base rounded-xl"
                        onClick={closeMobileMenu}
                      />
                    ))}
                  </nav>

                  {/* Mobile Authentication Section */}
                  {!user && (
                    <div className="flex flex-col gap-4 pt-6 border-t border-border/50 mt-auto">
                      <Button variant="ghost" className="w-full justify-start text-base rounded-xl border border-border/30 hover:border-primary/30 min-h-[44px]" data-testid="mobile-button-login" asChild>
                        <Link href="/login" onClick={closeMobileMenu}>
                          <User className="w-5 h-5 mr-4" />
                          Login to Account
                        </Link>
                      </Button>
                      <Button className="w-full justify-start text-base rounded-xl shadow-md min-h-[44px]" data-testid="mobile-button-signup" asChild>
                        <Link href="/signup" onClick={closeMobileMenu}>
                          <User className="w-5 h-5 mr-4" />
                          Create Account
                        </Link>
                      </Button>
                    </div>
                  )}

                  {/* Mobile User Section (Authenticated Users) */}
                  {user && (
                    <div className="flex flex-col gap-4 pt-6 border-t border-border/50 mt-auto">
                      {/* User Profile Display */}
                      <div className="flex items-center gap-4 p-5 bg-muted/50 rounded-xl border border-border/30">
                        <Avatar className="w-14 h-14 ring-2 ring-primary/20">
                          <AvatarImage src={user.profileImageUrl || ""} />
                          <AvatarFallback className="text-lg font-semibold">
                            {user.firstName?.[0]}{user.lastName?.[0]}
                          </AvatarFallback>
                        </Avatar>
                        <div className="flex-1 min-w-0">
                          <div className="text-lg font-semibold text-foreground truncate">
                            {user.firstName} {user.lastName}
                          </div>
                          <div className="text-sm text-muted-foreground capitalize truncate">
                            {user.role}
                          </div>
                        </div>
                      </div>

                      {/* Mobile User Menu Actions */}
                      <Button variant="ghost" className="w-full justify-start text-base rounded-xl border border-border/30 hover:border-primary/30 min-h-[44px]" data-testid="mobile-menu-item-profile" asChild>
                        <Link href="/profile">
                          <User className="w-5 h-5 mr-4" />
                          Account Profile
                        </Link>
                      </Button>
                      <Button variant="ghost" className="w-full justify-start text-base rounded-xl border border-border/30 hover:border-primary/30 min-h-[44px]" data-testid="mobile-menu-item-settings">
                        <Settings className="w-5 h-5 mr-4" />
                        System Preferences
                      </Button>
                      <Button 
                        variant="ghost" 
                        className="w-full justify-start text-base text-destructive hover:text-destructive rounded-xl border border-destructive/30 hover:border-destructive/50 min-h-[44px]" 
                        onClick={handleLogout}
                        data-testid="mobile-menu-item-logout"
                      >
                        <LogOut className="w-5 h-5 mr-4" />
                        Sign Out
                      </Button>
                    </div>
                  )}
                </div>
              </SheetContent>
            </Sheet>
          </div>
        </div>
      </div>
    </header>
  );
}

client/src/components/layout/sidebar.tsx.content:
/**
 * Sidebar Information Panel for Smart Student Hub
 * 
 * This comprehensive sidebar component provides contextual information and quick access
 * to essential academic data for the Smart Student Hub institutional platform. Rather than
 * duplicating main navigation, it focuses on user context, statistics, and notifications
 * to enhance the overall user experience.
 * 
 * Core Features:
 * - User profile information with academic details and current status
 * - Real-time academic statistics including activities, credits, and approvals
 * - Recent activity feed for quick access to latest submissions and updates
 * - Progress indicators for academic goals and portfolio completion
 * - Important notifications and deadline alerts
 * - Quick action buttons for common tasks and workflows
 * 
 * Information Sections:
 * - User Profile: Name, role, academic year, department, and profile picture
 * - Academic Stats: Total activities, skill credits, pending approvals, completion rates
 * - Recent Activities: Latest submissions with verification status and timestamps
 * - Progress Tracking: Portfolio completion, semester progress, achievement goals
 * - Notifications: Deadline reminders, faculty feedback, system announcements
 * - Quick Actions: Common shortcuts for frequent tasks
 * 
 * Professional Design:
 * - Clean, institutional interface complementing the main navigation
 * - Consistent styling with Higher Education Institution standards
 * - Responsive design ensuring optimal display across all device types
 * - Professional color scheme and typography suitable for academic environments
 * - Accessibility-compliant design patterns for inclusive educational use
 * 
 * User Experience:
 * - Contextual information relevant to current user session and activities
 * - Real-time updates for statistics and notifications
 * - Intuitive organization of information for quick scanning and access
 * - Professional presentation suitable for academic institutional environments
 * 
 * Technical Implementation:
 * - React functional components with TypeScript for type safety
 * - Integration with authentication system for personalized content
 * - Real-time data fetching for statistics and activity updates
 * - Responsive CSS using Tailwind CSS framework
 * - Optimized performance for smooth user experience
 */

import { useAuth } from "@/hooks/useAuth";
import { useQuery } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { cn } from "@/lib/utils";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { 
  User,
  BookOpen,
  Award,
  Clock,
  TrendingUp,
  Bell,
  CheckCircle2,
  Calendar,
  Target,
  Zap,
  AlertTriangle,
  Plus,
  FileText
} from "lucide-react";
import { Activity } from "@shared/schema";

/**
 * Student Statistics Interface
 * 
 * Defines the structure for student performance metrics and activity data
 * used throughout the sidebar for displaying real-time academic information.
 */
interface StudentStats {
  totalActivities: number;
  skillCredits: number;
  pendingApprovals: number;
  portfolioCompletion: number;
  currentGPA: number;
  semesterCredits: number;
}

/**
 * Recent Activity Interface
 * 
 * Defines the structure for recent activity items displayed in the sidebar
 */
interface RecentActivity {
  id: string;
  title: string;
  status: 'pending' | 'approved' | 'rejected';
  submittedAt: string;
  type: string;
}

/**
 * Quick Action Button Component
 * 
 * Renders individual quick action buttons for common tasks
 */
interface QuickActionProps {
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
  variant?: 'default' | 'outline';
}

function QuickAction({ icon, label, onClick, variant = 'outline' }: QuickActionProps) {
  return (
    <Button
      variant={variant}
      size="sm"
      className="w-full justify-start"
      onClick={onClick}
      data-testid={`button-${label.toLowerCase().replace(/\s+/g, '-')}`}
    >
      {icon}
      <span className="ml-2">{label}</span>
    </Button>
  );
}

/**
 * Sidebar Information Panel
 * 
 * Main sidebar component providing contextual information, statistics, and quick access
 * to essential academic data. Complements the main navigation by focusing on user context
 * and real-time information rather than duplicating navigation functionality.
 * 
 * @returns {JSX.Element | null} Complete sidebar information panel or null if user not authenticated
 */
export default function Sidebar() {
  // Authentication hook for user state and role verification
  const { user } = useAuth();
  const [, setLocation] = useLocation();

  // Return null if user is not authenticated
  if (!user) return null;

  // Fetch student statistics with loading state
  const { data: stats, isLoading: isLoadingStats } = useQuery<StudentStats>({
    queryKey: ["/api/students/stats"],
    retry: false,
  });

  // Fetch recent activities with loading state
  const { data: recentActivities, isLoading: isLoadingActivities } = useQuery<Activity[]>({
    queryKey: ["/api/students/activities"],
    retry: false,
  });

  // Helper function for safe date formatting
  const formatActivityDate = (dateValue: Date | string | null): string => {
    if (!dateValue) return 'Unknown';
    try {
      const date = typeof dateValue === 'string' ? new Date(dateValue) : dateValue;
      return date instanceof Date && !isNaN(date.getTime()) 
        ? date.toLocaleDateString()
        : 'Unknown';
    } catch {
      return 'Unknown';
    }
  };

  // Default values for display when data is loading
  const defaultStats = {
    totalActivities: stats?.totalActivities || 0,
    skillCredits: stats?.skillCredits || 0,
    pendingApprovals: stats?.pendingApprovals || 0,
    portfolioCompletion: stats?.portfolioCompletion || 0,
    currentGPA: stats?.currentGPA || 0,
    semesterCredits: stats?.semesterCredits || 0
  };

  // Format recent activities for display with safe date parsing
  const displayActivities = recentActivities?.slice(0, 3).map(activity => ({
    id: activity.id,
    title: activity.title,
    status: activity.status,
    submittedAt: formatActivityDate(activity.createdAt),
    type: activity.category === 'academic' ? 'Academic' : 
          activity.category === 'co-curricular' ? 'Co-curricular' :
          activity.category === 'extra-curricular' ? 'Extra-curricular' :
          activity.category === 'leadership' ? 'Leadership' :
          activity.category === 'mooc' ? 'Technical' : 
          activity.category.charAt(0).toUpperCase() + activity.category.slice(1)
  })) || [];

  return (
    <aside className="w-64 lg:w-72 xl:w-80 bg-background border-r border-border overflow-y-auto" data-testid="sidebar">
      <div className="p-3 lg:p-4 space-y-4 lg:space-y-6">

        {/* User Profile Section */}
        <Card>
          <CardContent className="p-3 lg:p-4">
            <div className="flex items-center gap-3">
              <Avatar className="w-10 h-10 lg:w-12 lg:h-12" data-testid="avatar-profile">
                <AvatarImage src={user.profileImageUrl || ""} />
                <AvatarFallback className="bg-primary text-primary-foreground">
                  {user.firstName?.[0]}{user.lastName?.[0]}
                </AvatarFallback>
              </Avatar>
              <div className="flex-1 min-w-0">
                <h3 className="font-semibold text-sm lg:text-base truncate" data-testid="text-username">
                  {user.firstName} {user.lastName}
                </h3>
                <p className="text-xs text-muted-foreground capitalize truncate" data-testid="text-user-role">
                  {user.role}
                </p>
                <div className="flex items-center mt-1 text-xs text-muted-foreground" data-testid="text-academic-info">
                  <BookOpen className="w-3 h-3 mr-1" />
                  GPA {defaultStats.currentGPA}
                </div>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Academic Statistics */}
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm lg:text-base flex items-center">
              <TrendingUp className="w-4 h-4 mr-2" />
              Overview
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            {isLoadingStats ? (
              <div className="space-y-3" data-testid="loading-stats">
                <div className="grid grid-cols-2 gap-2">
                  <div className="text-center p-2 bg-muted rounded-lg animate-pulse">
                    <div className="h-6 bg-muted-foreground/20 rounded mb-1"></div>
                    <div className="h-3 bg-muted-foreground/20 rounded"></div>
                  </div>
                  <div className="text-center p-2 bg-muted rounded-lg animate-pulse">
                    <div className="h-6 bg-muted-foreground/20 rounded mb-1"></div>
                    <div className="h-3 bg-muted-foreground/20 rounded"></div>
                  </div>
                </div>
              </div>
            ) : (
              <div className="grid grid-cols-2 gap-2">
                <div className="text-center p-2 bg-muted rounded-lg" data-testid="stat-activities">
                  <div className="text-base lg:text-lg font-bold text-primary">{defaultStats.totalActivities}</div>
                  <div className="text-xs text-muted-foreground">Activities</div>
                </div>
                <div className="text-center p-2 bg-muted rounded-lg" data-testid="stat-credits">
                  <div className="text-base lg:text-lg font-bold text-green-600">{defaultStats.skillCredits}</div>
                  <div className="text-xs text-muted-foreground">Credits</div>
                </div>
              </div>
            )}

            {!isLoadingStats && (
              <>
                <div className="space-y-2" data-testid="portfolio-progress">
                  <div className="flex justify-between text-xs">
                    <span>Portfolio Completion</span>
                    <span className="font-medium">{defaultStats.portfolioCompletion}%</span>
                  </div>
                  <Progress value={defaultStats.portfolioCompletion} className="h-2" />
                </div>

                {defaultStats.pendingApprovals > 0 && (
                  <div className="flex items-center justify-between p-2 bg-yellow-50 dark:bg-yellow-950 rounded-lg" data-testid="alert-pending-approvals">
                    <div className="flex items-center text-xs">
                      <Clock className="w-3 h-3 mr-1 text-yellow-600" />
                      Pending Approvals
                    </div>
                    <Badge variant="outline" className="text-yellow-600 border-yellow-600">
                      {defaultStats.pendingApprovals}
                    </Badge>
                  </div>
                )}
              </>
            )}
          </CardContent>
        </Card>

        {/* Recent Activities */}
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm lg:text-base flex items-center">
              <Award className="w-4 h-4 mr-2" />
              Recent
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            {isLoadingActivities ? (
              <div className="space-y-2" data-testid="loading-activities">
                {[...Array(3)].map((_, i) => (
                  <div key={i} className="flex items-start space-x-2 p-2 rounded-lg animate-pulse">
                    <div className="mt-1 w-3 h-3 bg-muted-foreground/20 rounded-full"></div>
                    <div className="flex-1 min-w-0 space-y-1">
                      <div className="h-3 bg-muted-foreground/20 rounded w-3/4"></div>
                      <div className="h-2 bg-muted-foreground/20 rounded w-1/2"></div>
                    </div>
                  </div>
                ))}
              </div>
            ) : displayActivities.length > 0 ? (
              displayActivities.map((activity, index) => (
                <div key={activity.id} className="flex items-start gap-2 p-2 rounded-lg hover:bg-muted/50 transition-colors" data-testid={`activity-item-${activity.id}`}>
                  <div className="mt-1">
                    {activity.status === 'approved' ? (
                      <CheckCircle2 className="w-3 h-3 text-green-600" />
                    ) : activity.status === 'pending' ? (
                      <Clock className="w-3 h-3 text-yellow-600" />
                    ) : (
                      <AlertTriangle className="w-3 h-3 text-red-600" />
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-medium truncate" data-testid={`text-activity-title-${activity.id}`}>{activity.title}</p>
                    <p className="text-xs text-muted-foreground" data-testid={`text-activity-meta-${activity.id}`}>
                      {activity.type} • {activity.submittedAt}
                    </p>
                  </div>
                </div>
              ))
            ) : (
              <p className="text-xs text-muted-foreground text-center py-4" data-testid="text-no-activities">
                No recent activities found
              </p>
            )}
          </CardContent>
        </Card>

        {/* Quick Actions */}
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm lg:text-base flex items-center">
              <Zap className="w-4 h-4 mr-2" />
              Actions
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            <QuickAction
              icon={<Calendar className="w-4 h-4" />}
              label="Deadlines"
              onClick={() => {}}
            />
            <QuickAction
              icon={<Bell className="w-4 h-4" />}
              label="Notifications"
              onClick={() => {}}
            />
            <QuickAction
              icon={<Target className="w-4 h-4" />}
              label="Goals"
              onClick={() => {}}
            />
          </CardContent>
        </Card>

        {/* Notifications/Alerts */}
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm lg:text-base flex items-center">
              <Bell className="w-4 h-4 mr-2" />
              Alerts
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            <div className="p-2 bg-blue-50 dark:bg-blue-950 rounded-lg" data-testid="alert-deadline">
              <div className="flex items-start gap-2">
                <Target className="w-3 h-3 mt-1 text-blue-600" />
                <div>
                  <p className="text-xs font-medium text-blue-900 dark:text-blue-100">
                    Portfolio Due
                  </p>
                  <p className="text-xs text-blue-700 dark:text-blue-300">
                    Jan 30, 2024
                  </p>
                </div>
              </div>
            </div>

            <div className="p-2 bg-green-50 dark:bg-green-950 rounded-lg" data-testid="alert-achievement">
              <div className="flex items-start gap-2">
                <CheckCircle2 className="w-3 h-3 mt-1 text-green-600" />
                <div>
                  <p className="text-xs font-medium text-green-900 dark:text-green-100">
                    Achievement Approved
                  </p>
                  <p className="text-xs text-green-700 dark:text-green-300">
                    ML Workshop verified
                  </p>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>

      </div>
    </aside>
  );
}

client/src/components/ui/activity-list.t.content:
/**
 * Activity List Component for Smart Student Hub
 * 
 * A comprehensive activity display component designed for showcasing student
 * achievements, faculty verification queues, and administrative analytics.
 * Provides professional formatting suitable for institutional environments.
 * 
 * Key Features:
 * - NAAC-compliant activity categorization with visual indicators
 * - Professional status badges for verification workflow
 * - Category-specific icons for immediate visual identification
 * - Interactive actions for viewing details and downloading certificates
 * - Loading states for enhanced user experience
 * - Responsive design optimized for various screen sizes
 * 
 * Activity Categories (NAAC Compliant):
 * - Academic: Research, publications, academic competitions
 * - Co-curricular: Technical events, skill development programs
 * - Extra-curricular: Cultural activities, social engagement
 * - Volunteering: Community service, social responsibility
 * - Internship: Industry experience, professional development
 * - Leadership: Student government, organizational roles
 * - MOOC: Online courses, professional certifications
 * 
 * Status Management:
 * - Pending: Awaiting faculty verification
 * - Approved: Faculty-verified and portfolio-ready
 * - Rejected: Requires revision or additional documentation
 * 
 * Professional Features:
 * - Institutional verification badges
 * - Date formatting with consistent standards
 * - Professional color coding for status and categories
 * - Certificate download capabilities for verified activities
 * - Detailed activity metadata display
 * 
 * Integration Points:
 * - Student dashboard activity feeds
 * - Faculty approval and verification interfaces
 * - Digital portfolio generation systems
 * - Administrative analytics and reporting tools
 */

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { 
  Eye, 
  Download, 
  Calendar, 
  Building2, 
  GraduationCap, 
  Trophy, 
  Target, 
  Heart, 
  Briefcase, 
  Crown, 
  Monitor,
  FileText 
} from "lucide-react";
import { cn } from "@/lib/utils";
import { Activity } from "@shared/schema";

/**
 * Activity List Component Props
 * 
 * Configuration interface for the activity list component,
 * enabling flexible display across different institutional contexts.
 */
interface ActivityListProps {
  activities: Activity[];                                    // Array of activities to display
  isLoading?: boolean;                                       // Loading state indicator
  showActions?: boolean;                                     // Whether to show action buttons
  onViewActivity?: (activity: Activity) => void;            // Callback for viewing activity details
  onDownloadCertificate?: (activity: Activity) => void;     // Callback for certificate download
  className?: string;                                        // Additional CSS classes
}

/**
 * Activity List Component
 * 
 * Professional activity display component for institutional activity
 * management and student achievement showcase interfaces.
 */

export default function ActivityList({
  activities,
  isLoading = false,
  showActions = true,
  onViewActivity,
  onDownloadCertificate,
  className
}: ActivityListProps) {

  const getStatusBadge = (status: string) => {
    const statusConfig = {
      pending: { className: "status-pending", label: "Pending" },
      approved: { className: "status-approved", label: "Approved" },
      rejected: { className: "status-rejected", label: "Rejected" }
    };

    const config = statusConfig[status as keyof typeof statusConfig] || statusConfig.pending;

    return (
      <Badge className={config.className} data-testid={`status-badge-${status}`}>
        {config.label}
      </Badge>
    );
  };

  const getCategoryIcon = (category: string) => {
    const categoryIcons = {
      academic: <GraduationCap className="w-5 h-5 text-blue-600" />,
      "co-curricular": <Trophy className="w-5 h-5 text-amber-600" />,
      "extra-curricular": <Target className="w-5 h-5 text-green-600" />,
      volunteering: <Heart className="w-5 h-5 text-red-600" />,
      internship: <Briefcase className="w-5 h-5 text-purple-600" />,
      leadership: <Crown className="w-5 h-5 text-yellow-600" />,
      mooc: <Monitor className="w-5 h-5 text-indigo-600" />
    };

    return categoryIcons[category as keyof typeof categoryIcons] || <FileText className="w-5 h-5 text-gray-600" />;
  };

  const formatDate = (dateValue: string | Date) => {
    const date = typeof dateValue === 'string' ? new Date(dateValue) : dateValue;
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  const formatCategory = (category: string) => {
    return category.split('-').map(word => 
      word.charAt(0).toUpperCase() + word.slice(1)
    ).join(' ');
  };

  if (isLoading) {
    return (
      <div className={cn("space-y-4", className)} data-testid="activity-list-loading">
        {[...Array(3)].map((_, index) => (
          <Card key={index} className="dashboard-card">
            <CardContent className="p-4">
              <div className="animate-pulse">
                <div className="flex items-center space-x-4">
                  <div className="w-12 h-12 bg-muted rounded-lg"></div>
                  <div className="flex-1 space-y-2">
                    <div className="h-4 bg-muted rounded w-3/4"></div>
                    <div className="h-3 bg-muted rounded w-1/2"></div>
                  </div>
                  <div className="w-20 h-6 bg-muted rounded"></div>
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    );
  }

  if (activities.length === 0) {
    return (
      <div className={cn("text-center py-8", className)} data-testid="activity-list-empty">
        <div className="w-16 h-16 bg-muted/50 rounded-full flex items-center justify-center mx-auto mb-4">
          <Building2 className="w-8 h-8 text-muted-foreground" />
        </div>
        <h3 className="text-lg font-medium text-foreground mb-2">No Activities Found</h3>
        <p className="text-muted-foreground text-sm">
          Start by uploading your achievements and certificates to build your portfolio.
        </p>
      </div>
    );
  }

  return (
    <div className={cn("space-y-4", className)} data-testid="activity-list">
      {activities.map((activity, index) => (
        <Card key={activity.id} className="dashboard-card hover:shadow-md transition-shadow">
          <CardContent className="p-4">
            <div className="flex items-start space-x-4" data-testid={`activity-item-${index}`}>
              {/* Activity Icon */}
              <div className="w-12 h-12 bg-primary/10 rounded-lg flex items-center justify-center text-xl">
                {getCategoryIcon(activity.category)}
              </div>

              {/* Activity Details */}
              <div className="flex-1 min-w-0">
                <div className="flex items-start justify-between">
                  <div className="flex-1 min-w-0">
                    <h4 className="text-sm font-medium text-foreground truncate" data-testid={`activity-title-${index}`}>
                      {activity.title}
                    </h4>
                    <div className="flex items-center space-x-4 mt-1 text-xs text-muted-foreground">
                      <span className="flex items-center" data-testid={`activity-organization-${index}`}>
                        <Building2 className="w-3 h-3 mr-1" />
                        {activity.organization}
                      </span>
                      <span className="flex items-center" data-testid={`activity-date-${index}`}>
                        <Calendar className="w-3 h-3 mr-1" />
                        {formatDate(activity.activityDate)}
                      </span>
                    </div>

                    {/* Description Preview */}
                    {activity.description && (
                      <p className="text-xs text-muted-foreground mt-2 line-clamp-2" data-testid={`activity-description-${index}`}>
                        {activity.description.length > 100 
                          ? `${activity.description.substring(0, 100)}...`
                          : activity.description
                        }
                      </p>
                    )}

                    {/* Category and Credits */}
                    <div className="flex items-center space-x-3 mt-3">
                      <Badge variant="outline" className="text-xs" data-testid={`activity-category-${index}`}>
                        {formatCategory(activity.category)}
                      </Badge>
                      {activity.skillCredits && activity.status === 'approved' && (
                        <span className="text-xs text-success font-medium" data-testid={`activity-credits-${index}`}>
                          +{activity.skillCredits} credits
                        </span>
                      )}
                    </div>

                    {/* Feedback for rejected activities */}
                    {activity.status === 'rejected' && activity.feedback && (
                      <div className="mt-2 p-2 bg-destructive/5 border border-destructive/20 rounded text-xs">
                        <p className="text-destructive" data-testid={`activity-feedback-${index}`}>
                          <strong>Feedback:</strong> {activity.feedback}
                        </p>
                      </div>
                    )}
                  </div>

                  {/* Status and Actions */}
                  <div className="flex items-center space-x-3 ml-4">
                    {getStatusBadge(activity.status)}

                    {showActions && (
                      <div className="flex items-center space-x-1">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => onViewActivity?.(activity)}
                          data-testid={`button-view-activity-${index}`}
                        >
                          <Eye className="w-4 h-4" />
                        </Button>

                        {activity.status === 'approved' && onDownloadCertificate && (
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => onDownloadCertificate(activity)}
                            data-testid={`button-download-certificate-${index}`}
                          >
                            <Download className="w-4 h-4" />
                          </Button>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

