              {width > 60 && height > 30 && (
                <>
                  <text
                    x={x + width / 2}
                    y={y + height / 2 - 7}
                    textAnchor="middle"
                    fill="#fff"
                    fontSize={Math.min(14, width / 6, height / 4)}
                    fontWeight="bold"
                  >
                    {name}
                  </text>
                  <text
                    x={x + width / 2}
                    y={y + height / 2 + 7}
                    textAnchor="middle"
                    fill="#fff"
                    fontSize={Math.min(10, width / 8, height / 6)}
                  >
                    {size} items
                  </text>
                </>
              )}
            </g>
          )}
        />
      </ResponsiveContainer>
    </ChartCard>
  );
});

// Chart 17: Approval SLA by Reviewer (Recharts Composed)
export interface ApprovalSLAData {
  reviewer: string;
  avgApprovalTime: number;
  slaTarget: number;
  totalReviewed: number;
  onTimePercentage: number;
  delayedCount: number;
