export const ApprovalSLAChart = memo<{
  data: ApprovalSLAData[];
  className?: string;
}>(({ data, className }) => {
  const config = {
    title: 'Approval SLA Performance',
    subtitle: 'Reviewer efficiency and turnaround metrics',
