import { motion, AnimatePresence, useAnimation, useInView } from 'framer-motion';
import Particles from '@tsparticles/react';
import { TypeAnimation } from 'react-type-animation';
import VanillaTilt from 'vanilla-tilt';
import { ClipLoader } from 'react-spinners';
import Swal from 'sweetalert2';
import zxcvbn from 'zxcvbn';
import Confetti from 'react-confetti';
import { 
  Eye, 
  EyeOff, 
  Mail, 
  Lock, 
  GraduationCap, 
  Users, 
  TrendingUp, 
  Award,
  User,
  Building,
  Hash,
  Check,
  X
} from 'lucide-react';
import { signUpUser } from '@/firebase/auth';

const signupSchema = z.object({
  firstName: z.string()
    .min(2, 'First name must be at least 2 characters')
    .max(50, 'First name must not exceed 50 characters')
    .regex(/^[a-zA-Z\s]+$/, 'First name should only contain letters'),
  lastName: z.string()
    .min(2, 'Last name must be at least 2 characters')
    .max(50, 'Last name must not exceed 50 characters')
    .regex(/^[a-zA-Z\s]+$/, 'Last name should only contain letters'),
  college: z.string()
    .min(2, 'College name must be at least 2 characters')
    .max(100, 'College name must not exceed 100 characters'),
  registrationNo: z.string()
    .min(3, 'Registration number must be at least 3 characters')
    .max(20, 'Registration number must not exceed 20 characters')
    .regex(/^[a-zA-Z0-9-]+$/, 'Registration number can only contain letters, numbers, and dashes'),
  email: z.string()
    .email('Please enter a valid email address')
    .min(1, 'Email is required'),
  password: z.string()
    .min(8, 'Password must be at least 8 characters')
    .regex(/[A-Z]/, 'Password must contain at least one uppercase letter')
    .regex(/[a-z]/, 'Password must contain at least one lowercase letter')
    .regex(/[0-9]/, 'Password must contain at least one number')
    .regex(/[^A-Za-z0-9]/, 'Password must contain at least one special character'),
  confirmPassword: z.string().min(1, 'Please confirm your password'),
}).refine((data) => data.password === data.confirmPassword, {
  message: "Passwords don't match",
  path: ['confirmPassword'],
});

type SignupFormData = z.infer<typeof signupSchema>;

export default function FirebaseSignup() {
  const [, setLocation] = useLocation();
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [focusedField, setFocusedField] = useState<string | null>(null);
  const [ripples, setRipples] = useState<Array<{ x: number; y: number; id: number }>>([]);
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  const [showConfetti, setShowConfetti] = useState(false);
  const [windowSize, setWindowSize] = useState({ width: window.innerWidth, height: window.innerHeight });
  const tiltRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const formRef = useRef<HTMLDivElement>(null);
  const glowControls = useAnimation();
  const isInView = useInView(formRef, { once: false, amount: 0.3 });

  const {
    register,
    handleSubmit,
    formState: { errors },
    watch,
  } = useForm<SignupFormData>({
    resolver: zodResolver(signupSchema),
    mode: 'onChange',
  });

  const formValues = watch();
  const passwordValue = watch('password');

  useEffect(() => {
    const handleResize = () => {
      setWindowSize({ width: window.innerWidth, height: window.innerHeight });
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    if (tiltRef.current) {
      VanillaTilt.init(tiltRef.current, {
        max: 15,
        speed: 400,
        glare: true,
        'max-glare': 0.3,
      });
    }
    return () => {
      if (tiltRef.current && (tiltRef.current as any).vanillaTilt) {
        (tiltRef.current as any).vanillaTilt.destroy();
      }
    };
  }, []);

  useEffect(() => {
    const animateGlow = async () => {
      await glowControls.start({
        x: ['0%', '200%'],
        transition: {
          duration: 3,
          repeat: Infinity,
          ease: 'linear',
        },
      });
    };
    animateGlow();
  }, [glowControls]);

  const passwordStrength = useMemo(() => {
    if (!passwordValue || passwordValue.length === 0) return null;
    return zxcvbn(passwordValue);
  }, [passwordValue]);

  const passwordRequirements = useMemo(() => {
    const pwd = passwordValue || '';
    return {
      length: pwd.length >= 8,
      uppercase: /[A-Z]/.test(pwd),
      lowercase: /[a-z]/.test(pwd),
      number: /[0-9]/.test(pwd),
      special: /[^A-Za-z0-9]/.test(pwd),
    };
  }, [passwordValue]);

