    if (score === 2) return { color: 'bg-yellow-500', label: 'Fair', width: '60%' };
    if (score === 3) return { color: 'bg-blue-500', label: 'Good', width: '80%' };
    return { color: 'bg-green-500', label: 'Strong', width: '100%' };
