import { useState, useEffect, useRef, MouseEvent } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useLocation } from 'wouter';
import { motion, AnimatePresence, useAnimation } from 'framer-motion';
import Particles from '@tsparticles/react';
import { TypeAnimation } from 'react-type-animation';
import VanillaTilt from 'vanilla-tilt';
import { ClipLoader } from 'react-spinners';
import Swal from 'sweetalert2';
import { Eye, EyeOff, Mail, Lock, GraduationCap, Users, TrendingUp, Award } from 'lucide-react';
import { signInUser, resetPassword } from '@/firebase/auth';

const signinSchema = z.object({
  email: z.string().email('Please enter a valid email address').min(1, 'Email is required'),
  password: z.string().min(6, 'Password must be at least 6 characters').min(1, 'Password is required'),
});

type SigninFormData = z.infer<typeof signinSchema>;

export default function FirebaseSignin() {
  const [, setLocation] = useLocation();
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [emailFocused, setEmailFocused] = useState(false);
  const [passwordFocused, setPasswordFocused] = useState(false);
  const [ripples, setRipples] = useState<Array<{ x: number; y: number; id: number }>>([]);
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  const tiltRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const glowControls = useAnimation();

  const {
    register,
    handleSubmit,
    formState: { errors },
    watch,
  } = useForm<SigninFormData>({
    resolver: zodResolver(signinSchema),
    mode: 'onChange',
  });

  const emailValue = watch('email');
  const passwordValue = watch('password');

  useEffect(() => {
    if (tiltRef.current) {
      VanillaTilt.init(tiltRef.current, {
        max: 15,
        speed: 400,
        glare: true,
        'max-glare': 0.3,
      });
    }
    return () => {
      if (tiltRef.current && (tiltRef.current as any).vanillaTilt) {
        (tiltRef.current as any).vanillaTilt.destroy();
      }
    };
  }, []);

  useEffect(() => {
    const animateGlow = async () => {
      await glowControls.start({
        x: ['0%', '200%'],
        transition: {
          duration: 3,
          repeat: Infinity,
          ease: 'linear',
        },
      });
    };
    animateGlow();
  }, [glowControls]);

  const handleMouseMove = (e: MouseEvent<HTMLButtonElement>) => {
    if (!buttonRef.current) return;
    const rect = buttonRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    setMousePosition({ x, y });
  };

  const handleRippleClick = (e: MouseEvent<HTMLButtonElement>) => {
    if (!buttonRef.current) return;
    const rect = buttonRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const id = Date.now();
    setRipples((prev) => [...prev, { x, y, id }]);
    setTimeout(() => {
      setRipples((prev) => prev.filter((ripple) => ripple.id !== id));
    }, 600);
  };

  const onSubmit = async (data: SigninFormData) => {
    setIsLoading(true);
    try {
      await signInUser(data.email, data.password);

      await Swal.fire({
        icon: 'success',
        title: 'Welcome Back!',
        text: 'You have successfully signed in.',
        showConfirmButton: false,
        timer: 2000,
        background: 'hsl(var(--card))',
        color: 'hsl(var(--card-foreground))',
      });

      setLocation('/dashboard');
    } catch (error: any) {
      if (error.message === 'EMAIL_NOT_VERIFIED') {
        await Swal.fire({
          icon: 'warning',
          title: 'Email Not Verified',
          text: 'Please verify your email before signing in. Redirecting to verification page...',
          showConfirmButton: false,
          timer: 2000,
          background: 'hsl(var(--card))',
          color: 'hsl(var(--card-foreground))',
        });
        setLocation('/email-verification');
      } else {
        await Swal.fire({
          icon: 'error',
          title: 'Sign In Failed',
          text: error.message || 'Failed to sign in. Please try again.',
          confirmButtonColor: 'hsl(var(--primary))',
          background: 'hsl(var(--card))',
          color: 'hsl(var(--card-foreground))',
        });
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleForgotPassword = async () => {
    const { value: email } = await Swal.fire({
      title: 'Reset Password',
      input: 'email',
      inputLabel: 'Enter your email address',
      inputPlaceholder: 'Enter your email',
      showCancelButton: true,
      confirmButtonText: 'Send Reset Link',
      confirmButtonColor: 'hsl(var(--primary))',
      background: 'hsl(var(--card))',
      color: 'hsl(var(--card-foreground))',
      inputValidator: (value) => {
        if (!value) {
          return 'You need to enter an email address!';
        }
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
          return 'Please enter a valid email address!';
        }
      },
    });

    if (email) {
      try {
        await resetPassword(email);
        await Swal.fire({
